std::string seal(std::string_view blob) {
  auto key = unique_pkey(EVP_PKEY_new_mac_key(EVP_PKEY_HMAC, nullptr, k, klen));
  auto ctx = unique_md_ctx(EVP_MD_CTX_new());
  unsigned char mac[32]; size_t len = sizeof mac;
  EVP_DigestSignInit(ctx.get(), nullptr, EVP_sha256(), nullptr, key.get());
  EVP_DigestSignUpdate(ctx.get(), blob.data(), blob.size());
  EVP_DigestSignFinal(ctx.get(), mac, &len);
  return b64url(blob) + "." + b64url({mac, len});   // response: Set-Cookie: sid=<...>; HttpOnly; Secure
}
